func (v PA) String() string {
	switch v {
	case PADB6:
		return "dB-6"
	case PADB4dot77:
		return "dB-4dot77"
	case PADBMinus3:
		return "dB-3"
	case PADB1dot77:
		return "dB-1dot77"
	case PADB0:
		return "dB0"
	case PADB1:
		return "dB1"
	case PADB2:
		return "dB2"
	case PADB3:
		return "dB3"
	default:
		return "unknown"
	}
}

